function readTextFile(input,callback){const f=input.files?.[0];if(!f)return;const reader=new FileReader();reader.onload=()=>callback(String(reader.result||''),f);reader.readAsText(f);input.value=''}

function allFieldSchemas(){const out=[];function walk(f){out.push(f);(f.sub_fields||[]).forEach(walk);(f.layouts||[]).forEach(l=>(l.sub_fields||[]).forEach(walk))}(currentUi?.acf||[]).forEach(g=>(g.fields||[]).forEach(walk));return out}
function findSchema(key){return allFieldSchemas().find(f=>String(f.key)===String(key))||null}
function optionList(field,value){const values=Array.isArray(value)?value.map(String):[String(value??'')];let h='';Object.entries(field.choices||{}).forEach(([k,label])=>{h+='<option value="'+esc(k)+'" '+(values.includes(String(k))?'selected':'')+'>'+esc(label)+'</option>'});return h}
function fieldHeader(field){return '<div class="npm9-field-top"><label class="npm9-field-label">'+esc(field.label)+(field.required?' *':'')+'</label><span class="npm9-badge">ACF '+esc(field.type)+'</span></div>'}
function mediaPreview(id,field){if(!id)return '<span>No file</span>';if(field.image&&String(field.image.id)===String(id)&&field.image.thumb)return '<img src="'+esc(field.image.thumb)+'" alt="">';return '<span>Attachment #'+esc(id)+'</span>'}
function galleryPreview(field,ids){const byId={};(field.gallery||[]).forEach(x=>byId[String(x.id)]=x);if(!ids.length)return '<span class="npm9-empty">No images selected</span>';return ids.map(id=>{const x=byId[String(id)]||{};return '<div class="npm9-gallery-item" data-id="'+esc(id)+'">'+(x.thumb?'<img src="'+esc(x.thumb)+'" alt="">':'<span>#'+esc(id)+'</span>')+'<button type="button" class="npm9-gallery-remove" aria-label="Remove">×</button></div>'}).join('')}

function renderField(field,value,opts={}){const id=uid();if(value===undefined||value===null)value=blankFor(field);const structural=['tab','accordion','message'];if(structural.includes(field.type)){return '<div class="npm9-acf-structural npm9-'+esc(field.type)+'">'+(field.type==='message'?'<strong>'+esc(field.label)+'</strong><div>'+esc(field.instructions||'')+'</div>':'<strong>'+esc(field.label)+'</strong>')+'</div>'}
 let body='';const data=' data-field-key="'+esc(field.key)+'" data-field-name="'+esc(field.name)+'" data-field-type="'+esc(field.type)+'" ';
 if(['textarea','wysiwyg','oembed','code_editor'].includes(field.type)){body='<textarea class="npm9-control-main" id="'+id+'">'+esc(asText(value))+'</textarea>'}
 else if(['image','file'].includes(field.type)){const v=(typeof value==='object'&&value)?(value.id||value.ID||value.attachment_id||0):parseInt(value||0,10);body='<div class="npm9-media npm9-media-field"><div class="npm9-media-preview npm9-media-preview-action" role="button" tabindex="0" title="Tap to choose or replace">'+mediaPreview(v,field)+'</div><div><input type="hidden" class="npm9-control-main npm9-media-id" value="'+esc(v||0)+'"><div class="npm9-media-actions"><button type="button" class="button npm9-pick-media" data-kind="'+esc(field.type)+'">Choose / Replace</button><button type="button" class="button npm9-clear-media">Clear</button></div><small>Attachment ID: <span class="npm9-media-id-label">'+esc(v||0)+'</span></small></div></div>'}
 else if(field.type==='gallery'){const ids=(Array.isArray(value)?value:[]).map(x=>parseInt(typeof x==='object'?(x.id||x.ID||0):x,10)).filter(Boolean);body='<div class="npm9-gallery"><input type="hidden" class="npm9-control-main npm9-gallery-ids" value="'+esc(JSON.stringify(ids))+'"><div class="npm9-gallery-grid">'+galleryPreview(field,ids)+'</div><button type="button" class="button npm9-gallery-pick">Add / Choose Images</button></div>'}
 else if(field.type==='true_false'){body='<label class="npm9-switch-line"><input class="npm9-control-main" type="checkbox" '+(parseInt(value,10)?'checked':'')+'> <span>Yes / enabled</span></label>'}
 else if(field.type==='select'||field.type==='radio'||field.type==='button_group'){if(field.type==='select'){body='<select class="npm9-control-main" '+(field.multiple?'multiple':'')+'>'+optionList(field,value)+'</select>'}else{const vals=Array.isArray(value)?value.map(String):[String(value??'')];body='<div class="npm9-choice-list">'+Object.entries(field.choices||{}).map(([k,label])=>'<label><input class="npm9-control-choice" name="'+id+'" type="radio" value="'+esc(k)+'" '+(vals.includes(String(k))?'checked':'')+'> '+esc(label)+'</label>').join('')+'</div>'}}
 else if(field.type==='checkbox'){const vals=Array.isArray(value)?value.map(String):[];body='<div class="npm9-choice-list">'+Object.entries(field.choices||{}).map(([k,label])=>'<label><input class="npm9-control-choice" type="checkbox" value="'+esc(k)+'" '+(vals.includes(String(k))?'checked':'')+'> '+esc(label)+'</label>').join('')+'</div>'}
 else if(field.type==='group'){const obj=(value&&typeof value==='object'&&!Array.isArray(value))?value:{};body='<div class="npm9-group-fields">'+(field.sub_fields||[]).map(sub=>renderField(sub,obj[sub.name],{nested:true})).join('')+'</div>'}
 else if(field.type==='repeater'){const rows=Array.isArray(value)?value:[];body='<div class="npm9-complex-head"><span>'+rows.length+' row(s)</span><button type="button" class="button npm9-add-repeater">Add Row</button></div><div class="npm9-rows npm9-repeater-rows">'+rows.map((row,i)=>renderRepeaterRow(field,row,i)).join('')+'</div>'}
 else if(field.type==='flexible_content'){const rows=Array.isArray(value)?value:[];const layoutOptions=(field.layouts||[]).map(l=>'<option value="'+esc(l.name)+'">'+esc(l.label||l.name)+'</option>').join('');body='<div class="npm9-flex-add"><select class="npm9-flex-layout-select">'+layoutOptions+'</select><button type="button" class="button npm9-add-flex">Add Layout</button></div><div class="npm9-rows npm9-flex-rows">'+rows.map((row,i)=>renderFlexRow(field,row,i)).join('')+'</div>'}
 else if(field.type==='link'){const v=(value&&typeof value==='object'&&!Array.isArray(value))?value:{};body='<div class="npm9-link-grid"><input class="npm9-link-url" type="url" placeholder="URL" value="'+esc(v.url||'')+'"><input class="npm9-link-title" type="text" placeholder="Link text" value="'+esc(v.title||'')+'"><label><input class="npm9-link-target" type="checkbox" '+(v.target==='_blank'?'checked':'')+'> Open new tab</label></div>'}
 else if(['relationship','post_object','taxonomy','user'].includes(field.type)){body='<textarea class="npm9-control-main npm9-id-list" placeholder="IDs as JSON array, e.g. [12,34]">'+esc(asText(value))+'</textarea><small>Use WordPress IDs. This remains intentionally simple on mobile.</small>'}
 else if(['google_map','clone'].includes(field.type)){body='<textarea class="npm9-control-main npm9-json-field">'+esc(asText(value))+'</textarea><small>Structured value. Edit as JSON.</small>'}
 else{let type=['number','range'].includes(field.type)?'number':field.type==='url'?'url':field.type==='email'?'email':'text';let attrs='';if(field.min!==''&&field.min!=null)attrs+=' min="'+esc(field.min)+'"';if(field.max!==''&&field.max!=null)attrs+=' max="'+esc(field.max)+'"';if(field.step!==''&&field.step!=null)attrs+=' step="'+esc(field.step)+'"';body='<input class="npm9-control-main" type="'+type+'" value="'+esc(value??'')+'"'+attrs+'>'}
 return '<div class="npm9-acf-field '+(opts.nested?'npm9-nested-field':'npm9-root-field')+'"'+data+'>'+fieldHeader(field)+'<div class="npm9-field-body">'+body+'</div>'+(field.instructions?'<small class="npm9-help">'+esc(field.instructions)+'</small>':'')+'</div>'
}
function rowActions(){return '<div class="npm9-row-actions"><button type="button" class="button npm9-row-up" title="Move up">↑</button><button type="button" class="button npm9-row-down" title="Move down">↓</button><button type="button" class="button npm9-row-duplicate">Duplicate</button><button type="button" class="button npm9-row-remove">Remove</button></div>'}
function renderRepeaterRow(field,row,index){const obj=row&&typeof row==='object'?row:{};return '<div class="npm9-row" data-row-index="'+index+'"><div class="npm9-row-head"><strong>Row '+(index+1)+'</strong>'+rowActions()+'</div><div class="npm9-row-fields">'+(field.sub_fields||[]).map(sub=>renderField(sub,obj[sub.name],{nested:true})).join('')+'</div></div>'}
function renderFlexRow(field,row,index){const obj=row&&typeof row==='object'?row:{};const layoutName=obj.acf_fc_layout||field.layouts?.[0]?.name||'';const layout=(field.layouts||[]).find(l=>l.name===layoutName)||field.layouts?.[0]||{name:layoutName,label:layoutName,sub_fields:[]};return '<div class="npm9-row npm9-flex-row" data-row-index="'+index+'" data-layout="'+esc(layout.name)+'"><div class="npm9-row-head"><strong>'+esc(layout.label||layout.name)+' <span class="npm9-badge">'+esc(layout.name)+'</span></strong>'+rowActions()+'</div><div class="npm9-row-fields">'+(layout.sub_fields||[]).map(sub=>renderField(sub,obj[sub.name],{nested:true})).join('')+'</div></div>'}
function renumberRows($wrap){$wrap.children('.npm9-row').each(function(i){$(this).attr('data-row-index',i).find('> .npm9-row-head > strong').first().contents().first()[0]&&null});}

function renderAcfTabSet(tabs,placement){if(!tabs.length)return '';const setId=uid();let nav='<div class="npm9-acf-tab-nav" role="tablist" aria-label="ACF sections">';tabs.forEach((tab,i)=>{nav+='<button type="button" class="npm9-acf-tab-button '+(i===0?'is-active':'')+'" role="tab" aria-selected="'+(i===0?'true':'false')+'" data-tab-target="'+setId+'-'+i+'">'+esc(tab.label||('Section '+(i+1)))+'</button>'});nav+='</div>';let panels='';tabs.forEach((tab,i)=>{panels+='<div class="npm9-acf-tab-panel" id="'+setId+'-'+i+'" role="tabpanel" '+(i===0?'':'hidden')+'>'+(tab.fields||[]).map(f=>renderField(f,f.value)).join('')+'</div>'});return '<div class="npm9-acf-tabs npm9-tabs-'+esc(placement||'top')+'">'+nav+'<div class="npm9-acf-tab-panels">'+panels+'</div></div>'}
function renderAcfSequence(fields){let html='',plain=[],tabs=null,currentTab=null,placement='top';function flushPlain(){if(plain.length){html+=plain.map(f=>renderField(f,f.value)).join('');plain=[]}}function flushTabs(){if(tabs&&tabs.length)html+=renderAcfTabSet(tabs,placement);tabs=null;currentTab=null;placement='top'}(fields||[]).forEach(field=>{if(field.type==='tab'){if(field.endpoint)flushTabs();if(!field.label)return;if(!tabs){flushPlain();tabs=[];placement=field.placement||'top'}currentTab={label:field.label,fields:[]};tabs.push(currentTab);return}if(tabs&&currentTab)currentTab.fields.push(field);else plain.push(field)});flushTabs();flushPlain();return html}
function renderAcfGroup(group){return '<section class="npm9-card npm9-acf-group"><div class="npm9-section-head"><h2>'+esc(group.title)+'</h2><span class="npm9-badge">ACF Group</span></div>'+renderAcfSequence(group.fields||[])+'</section>'}

function ninecfValueText(v){if(v===null||typeof v==='undefined')return '';if(typeof v==='string'||typeof v==='number')return String(v);try{return JSON.stringify(v,null,2)}catch(e){return String(v)}}
function humanizeKey(k){return String(k||'').replace(/^_+/,'').replace(/[_-]+/g,' ').replace(/\b\w/g,c=>c.toUpperCase())}
