 let control='';
 if(isShallowScalarObject(f.value)){
   const rows=Object.keys(f.value).map(k=>{const v=f.value[k],kt=typeof v;let c='';if(kt==='boolean'){c='<label class="npm9-switch-line"><input type="checkbox" class="npm9-ninecf-subcontrol" data-sub-key="'+esc(k)+'" data-sub-type="boolean" '+(v?'checked':'')+'> <span>'+esc(humanizeKey(k))+'</span></label>'}else if(kt==='number'){c='<label><span>'+esc(humanizeKey(k))+'</span><input type="number" class="npm9-ninecf-subcontrol" data-sub-key="'+esc(k)+'" data-sub-type="number" value="'+esc(v)+'"></label>'}else{c='<label><span>'+esc(humanizeKey(k))+'</span><input type="text" class="npm9-ninecf-subcontrol" data-sub-key="'+esc(k)+'" data-sub-type="text" value="'+esc(v??'')+'"></label>'}return '<div class="npm9-ninecf-subfield">'+c+'</div>'}).join('');
   control='<details class="npm9-ninecf-object" data-ninecf-id="'+id+'" open><summary>Post-specific controls</summary><div class="npm9-ninecf-object-grid">'+rows+'</div></details>';
 }else if(enumVals.length&&['text','status','number'].includes(type)){control='<select class="npm9-ninecf-control" data-ninecf-id="'+id+'" data-ninecf-type="'+esc(type)+'">'+enumVals.map(v=>'<option value="'+esc(v)+'" '+(String(v)===String(f.value)?'selected':'')+'>'+esc(Object.prototype.hasOwnProperty.call(enumLabels,String(v))?enumLabels[String(v)]:v)+'</option>').join('')+'</select>'}
