$(document).on('click','.npm9-row-remove',function(){const $rows=$(this).closest('.npm9-rows');$(this).closest('.npm9-row').remove();renumberRows($rows)}).on('click','.npm9-row-up',function(){const $row=$(this).closest('.npm9-row'),$prev=$row.prev('.npm9-row');if($prev.length)$row.insertBefore($prev);renumberRows($row.parent())}).on('click','.npm9-row-down',function(){const $row=$(this).closest('.npm9-row'),$next=$row.next('.npm9-row');if($next.length)$row.insertAfter($next);renumberRows($row.parent())}).on('click','.npm9-row-duplicate',function(){const $row=$(this).closest('.npm9-row'),$parentField=$row.closest('.npm9-acf-field'),schema=findSchema($parentField.data('field-key'));if(!schema)return;let data={};directChildFields($row.children('.npm9-row-fields')).each(function(){data[$(this).data('field-name')]=readField($(this))});let html='';if(String($parentField.data('field-type'))==='flexible_content'){data.acf_fc_layout=String($row.data('layout'));html=renderFlexRow(schema,data,$row.index()+1)}else html=renderRepeaterRow(schema,data,$row.index()+1);$row.after(html);renumberRows($row.parent())});

