$(document).on('click','.npm9-ninecf-export',function(){if(!currentPostId)return;const $b=$(this).prop('disabled',true);ajax('9cf_export',{post_id:currentPostId,mode:$(this).data('mode')||'current',format:$(this).data('format')||'9cf'}).done(r=>{if(r.success){download(r.data.filename,r.data.mime,r.data.content);toast('9CF downloaded. '+(r.data.summary?.total_fields||'')+' fields inventoried.')}else toast(r.data?.message||'9CF export failed.',true)}).always(()=>$b.prop('disabled',false))});
$('#npm9-ninecf-import').on('click',()=>$('#npm9-ninecf-file').trigger('click'));
$('#npm9-ninecf-file').on('change',function(){const f=this.files?.[0];if(!f)return;const rd=new FileReader();rd.onload=()=>{const content=String(rd.result||'');ajax('9cf_preview',{post_id:currentPostId,content}).done(r=>{if(!r.success){toast(r.data?.message||'Could not read 9CF file.',true);return}const d=r.data||{},warnings=(d.warnings||[]).join('\n'),safe=(d.safeChanges||d.changes||[]),blocked=Number(d.blockedCount||0);let msg='Apply '+safe.length+' safe numbered 9CF field change(s) to this post? A recovery snapshot will be saved first.'+(blocked?'\n\n'+blocked+' field(s) will be skipped because they are protected, conflicted, invalid or no longer exist.':'');if(warnings)msg+='\n\nWarnings:\n'+warnings;const blockedItems=[...(d.conflicts||[]),...(d.invalidFields||[]),...(d.protectedFields||[])].slice(0,8);if(blockedItems.length)msg+='\n\nBlocked fields:\n'+blockedItems.map(x=>(x.code||x.id||'?')+' — '+(x.label||'')+(x.reason?' ('+x.reason+')':'')).join('\n');const ok=confirm(msg);if(!ok){toast('9CF import cancelled.');return}ajax('9cf_apply',{post_id:currentPostId,content,confirm_risk:d.requiresConfirmation?1:0}).done(x=>{if(x.success){clearPhoneDraft(currentPostId);toast(x.data?.message||'9CF applied.');loadPost(currentPostId)}else toast(x.data?.message||'9CF import failed.',true)})});};rd.readAsText(f);this.value=''});
