$('#npm9-import-btn').on('click',()=>$('#npm9-import-file').trigger('click'));$('#npm9-import-file').on('change',function(){const f=this.files?.[0];if(!f)return;const reader=new FileReader();reader.onload=()=>{pendingImport=String(reader.result||'');ajax('preview_import',{post_id:currentPostId,content:pendingImport}).done(res=>{if(!res.success){toast(res.data?.message||'Import file could not be read.',true);return}renderImportPreview(res.data)});};reader.readAsText(f);this.value=''});
function previewVal(v){const s=asText(v);return s.length>180?s.slice(0,180)+'…':s}
function renderImportPreview(data){let h='<h2>Import Preview</h2>';if(data.targetWarning)h+='<div class="npm9-warning">'+esc(data.targetWarning)+'</div>';h+='<p><strong>'+data.changes.length+'</strong> top-level field changes detected. A recovery snapshot will be saved before import.</p><div class="npm9-change-list">'+data.changes.slice(0,100).map(c=>'<div class="npm9-change"><strong>'+esc(c.section+' → '+c.field)+'</strong><br><small>Current: '+esc(previewVal(c.old))+'</small><br><small>Incoming: '+esc(previewVal(c.new))+'</small></div>').join('')+'</div>';if(data.requiresMismatchConfirmation)h+='<label class="npm9-confirm-mismatch"><input type="checkbox" id="npm9-confirm-mismatch"> I understand this file targets another post and I still want to apply it to the currently selected post.</label>';h+='<button type="button" class="button button-primary npm9-import-apply" '+(data.requiresMismatchConfirmation?'disabled':'')+'>Apply Import to Selected Post</button>';$('#npm9-import-preview').html(h).prop('hidden',false).data('mismatch',!!data.requiresMismatchConfirmation);$('html,body').animate({scrollTop:$('#npm9-import-preview').offset().top-80},150)}
$(document).on('change','#npm9-confirm-mismatch',function(){$('.npm9-import-apply').prop('disabled',!this.checked)}).on('click','.npm9-import-apply',function(){if(!pendingImport)return;const confirmMismatch=$('#npm9-confirm-mismatch').is(':checked')?1:0,$b=$(this).prop('disabled',true).text('Applying…');ajax('apply_import',{post_id:currentPostId,content:pendingImport,confirm_mismatch:confirmMismatch}).done(res=>{if(res.success){clearPhoneDraft(currentPostId);toast(res.data.message||'Import applied.');pendingImport='';$('#npm9-import-preview').prop('hidden',true);loadPost(currentPostId)}else toast(res.data?.message||'Import failed.',true)}).always(()=>$b.prop('disabled',false).text('Apply Import to Selected Post'))});

$('#npm9-create-import-btn').on('click',()=>$('#npm9-create-import-file').trigger('click'));$('#npm9-create-import-file').on('change',function(){const f=this.files?.[0];if(!f)return;const rd=new FileReader();rd.onload=()=>{pendingCreateImport=String(rd.result||'');ajax('preview_create_import',{content:pendingCreateImport,post_type:$('#npm9-post-type').val()}).done(r=>{if(!r.success){toast(r.data?.message||'Could not read package.',true);return}const d=r.data;$('#npm9-create-preview').html('<h3>Create New '+esc(d.postTypeLabel)+'</h3><p><strong>'+esc(d.title)+'</strong></p><p>Post type: <code>'+esc(d.postType)+'</code> · ACF fields: '+d.acfCount+' · Custom meta fields: '+d.metaCount+'</p><p>This creates a new post; it does not overwrite an existing post.</p><button type="button" class="button button-primary" id="npm9-create-apply">Create New Post</button>').prop('hidden',false)});};rd.readAsText(f);this.value=''});
